using Microsoft.Data.Sqlite;using OncaPDV.Application;using OncaPDV.Domain;using OncaPDV.Infrastructure;
namespace OncaPDV.Tests;
public sealed class AdvancedUpdateTests
{
 [Fact]public async Task Cancel_sale_reverses_stock_cash_and_keeps_history(){using var e=new Env();var p=await e.Product("CANCEL",20,10);var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart();cart.Add(p,2);var sale=await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.Cash,20,20)],op,session.Id);Assert.Equal(8,await e.Decimal("SELECT stock FROM products WHERE id=$id",("$id",p.Id)));await new AdvancedOperationsService(e.Db).CancelSaleAsync(sale.Id,op,"erro de lançamento");Assert.Equal(10,await e.Decimal("SELECT stock FROM products WHERE id=$id",("$id",p.Id)));Assert.Equal("Cancelled",await e.Text("SELECT status FROM sales WHERE id=$id",("$id",sale.Id)));Assert.Equal(0,await e.Decimal("SELECT COALESCE(SUM(amount),0) FROM cash_movements WHERE origin_id=$id",("$id",sale.Id)));Assert.Equal(1,await e.Long("SELECT COUNT(*) FROM sale_events WHERE sale_id=$id AND event_type='Cancelled'",("$id",sale.Id)));}
 [Fact]public async Task Cancel_credit_sale_with_receipt_reverses_receipt_cash_and_debt(){using var e=new Env();var customer=await e.Customer();var p=await e.Product("CREDIT-CANCEL",100,5);var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart{CustomerId=customer.Id};cart.Add(p);var sale=await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.StoreCredit,100)],op,session.Id);var credit=new SqliteCreditRepository(e.Db,new SystemClock());var account=(await credit.ByCustomerAsync(customer.Id)).Single();await credit.ReceiveAsync(account.Id,40,PaymentMethod.Pix,op,session.Id,"parcial");await new AdvancedOperationsService(e.Db).CancelSaleAsync(sale.Id,op,"cancelar crediário");Assert.Equal("Cancelled",await e.Text("SELECT status FROM credit_accounts WHERE id=$id",("$id",account.Id)));Assert.Equal(0,await e.Decimal("SELECT balance FROM credit_accounts WHERE id=$id",("$id",account.Id)));Assert.Equal(1,await e.Long("SELECT COUNT(*) FROM credit_receipt_reversals WHERE account_id=$id",("$id",account.Id)));Assert.Equal(0,await e.Decimal("SELECT COALESCE(SUM(amount),0) FROM cash_movements WHERE origin_id=$id AND type='StoreCreditReceipt'",("$id",account.Id)));}
 [Fact]public async Task Reverse_credit_receipt_restores_balance_and_cash(){using var e=new Env();var customer=await e.Customer();var p=await e.Product("REV",50,3);var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart{CustomerId=customer.Id};cart.Add(p);await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.StoreCredit,50)],op,session.Id);var cr=new SqliteCreditRepository(e.Db,new SystemClock());var account=(await cr.ByCustomerAsync(customer.Id)).Single();var receipt=await cr.ReceiveAsync(account.Id,20,PaymentMethod.Cash,op,session.Id,null);await new AdvancedOperationsService(e.Db).ReverseCreditReceiptAsync(receipt.Id,op,"lançado errado");Assert.Equal(50,await e.Decimal("SELECT balance FROM credit_accounts WHERE id=$id",("$id",account.Id)));Assert.Equal(0,await e.Decimal("SELECT COALESCE(SUM(amount),0) FROM cash_movements WHERE origin_id=$id",("$id",account.Id)));}
 [Fact]public async Task Payment_method_change_adjusts_cash(){using var e=new Env();var p=await e.Product("PAY",30,4);var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart();cart.Add(p);var sale=await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.Cash,30,30)],op,session.Id);await new AdvancedOperationsService(e.Db).ChangeSinglePaymentMethodAsync(sale.Id,PaymentMethod.Pix,op,"cliente pagou pix");Assert.Equal("Pix",await e.Text("SELECT method FROM payments WHERE sale_id=$id",("$id",sale.Id)));Assert.Equal(30,await e.Decimal("SELECT COALESCE(SUM(amount),0) FROM cash_movements WHERE origin_id=$id",("$id",sale.Id)));Assert.Equal(1,await e.Long("SELECT COUNT(*) FROM sale_events WHERE sale_id=$id AND event_type='PaymentChanged'",("$id",sale.Id)));}
 [Fact]public async Task Quote_is_saved_without_stock_change_and_can_be_loaded(){using var e=new Env();var p=await e.Product("QUOTE",12,8);var cart=new Cart();cart.Add(p,2);var ops=new AdvancedOperationsService(e.Db);var q=await ops.SaveQuoteAsync(cart);Assert.Equal(8,await e.Decimal("SELECT stock FROM products WHERE id=$id",("$id",p.Id)));var loaded=await ops.LoadQuoteAsync(q.Id);Assert.Single(loaded.Items);Assert.Equal(24,loaded.Total);await ops.MarkQuoteConvertedAsync(q.Id);Assert.Equal("Converted",await e.Text("SELECT status FROM quotes WHERE id=$id",("$id",q.Id)));}
 [Fact]public async Task Fiscal_draft_is_saved_then_marked_pending_without_fake_authorization(){using var e=new Env();var p=await e.Product("FISC",15,3);var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart();cart.Add(p);var sale=await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.Pix,15)],op,session.Id);var ops=new AdvancedOperationsService(e.Db);await ops.SaveFiscalDraftAsync(sale.Id);var d=(await ops.FiscalDraftsAsync()).Single();Assert.Equal("Draft",d.Status);await ops.MarkFiscalPendingAsync(d.Id);Assert.Equal("Pending",await e.Text("SELECT status FROM fiscal_drafts WHERE id=$id",("$id",d.Id)));Assert.Equal("Pending",await e.Text("SELECT fiscal_status FROM sales WHERE id=$id",("$id",sale.Id)));}
 [Fact]public async Task Closed_cash_can_be_reopened_with_audit(){using var e=new Env();var op=Guid.NewGuid();await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);await new OperationalService(e.Db,e.Paths).CloseCashAsync(op,0);var id=await new AdvancedOperationsService(e.Db).ReopenLastCashAsync(op,"conferência");Assert.Null(await e.NullableText("SELECT closed_at FROM cash_sessions WHERE id=$id",("$id",id)));Assert.Equal(1,await e.Long("SELECT COUNT(*) FROM cash_reopen_events WHERE session_id=$id",("$id",id)));}
 [Fact]public async Task Cart_recovery_still_works(){using var e=new Env();var p=await e.Product("RECOVER",9,10);var cart=new Cart();cart.Add(p,3);var store=new JsonCartRecoveryStore(e.Paths);await store.SaveAsync(cart);var recovered=await store.LoadAsync();Assert.NotNull(recovered);Assert.Equal(27,recovered!.Total);}
 [Fact]public async Task Search_sales_finds_product_customer_and_cancelled(){using var e=new Env();var customer=await e.Customer("Cliente Busca");var p=await e.Product("SEARCH-CODE",11,4,"Produto Especial");var op=Guid.NewGuid();var session=await new SqliteCashSessionRepository(e.Db,new SystemClock()).GetOrOpenAsync(op);var cart=new Cart{CustomerId=customer.Id};cart.Add(p);var sale=await new SqliteSaleRepository(e.Db,new SystemClock()).CompleteAsync(cart,[new(PaymentMethod.Pix,11)],op,session.Id);var ops=new AdvancedOperationsService(e.Db);Assert.Single(await ops.SearchSalesAsync("Especial"));await ops.CancelSaleAsync(sale.Id,op,"teste");Assert.Single(await ops.SearchSalesAsync("Cliente Busca","Cancelled"));}
 private sealed class Env:IDisposable{public string Root{get;}=Path.Combine(Path.GetTempPath(),"onca-advanced-"+Guid.NewGuid());public AppPaths Paths{get;}public OncaDatabase Db{get;}public Env(){Paths=new(Root,Path.Combine(Root,"data"),Path.Combine(Root,"backups"),Path.Combine(Root,"logs"),Path.Combine(Root,"exports"),Path.Combine(Root,"print"));Db=new(Paths);Db.Migrate();}public async Task<Product> Product(string code,decimal price,decimal stock,string name="Produto"){var p=new Product(Guid.NewGuid(),code,null,name,null,null,null,1,price,stock,0,"UN",null,null,true);await new SqliteProductRepository(Db).SaveAsync(p);return p;}public async Task<CustomerProfile> Customer(string name="Cliente"){var c=new CustomerProfile(Guid.NewGuid(),name,null,null,"11999999999",null,null,null,"Rua Teste","10",null,"Centro","Votorantim","SP",null,true);await new SqliteCustomerRepository(Db).SaveAsync(c);return c;}public async Task<decimal> Decimal(string sql,params(string,object)[] ps)=>Convert.ToDecimal(await Scalar(sql,ps));public async Task<long> Long(string sql,params(string,object)[] ps)=>Convert.ToInt64(await Scalar(sql,ps));public async Task<string> Text(string sql,params(string,object)[] ps)=>Convert.ToString(await Scalar(sql,ps))!;public async Task<string?> NullableText(string sql,params(string,object)[] ps){var v=await Scalar(sql,ps);return v is null||v is DBNull?null:Convert.ToString(v);}private async Task<object?> Scalar(string sql,params(string,object)[] ps){await using var c=Db.Open();await using var q=c.CreateCommand();q.CommandText=sql;foreach(var p in ps)q.Parameters.AddWithValue(p.Item1,p.Item2 is Guid id?id.ToString():p.Item2);return await q.ExecuteScalarAsync();}public void Dispose(){SqliteConnection.ClearAllPools();if(Directory.Exists(Root))Directory.Delete(Root,true);}}
}
